using System;using System.IO;using System.Linq;using UnityEngine;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class F1StoryLitterGround {public static object Run(){string root=Path.GetFullPath(Application.dataPath+"/../../..");var points=JObject.Parse(File.ReadAllText(root+"/SourceAssets/F1_EnvironmentalStory/litter_mesh.json"))["v"];var rows=points.Select(q=>{var p=q.Values<float>().ToArray();bool hit=Physics.Raycast(new Vector3(p[0],.7f,p[2]),Vector3.down,out var h,3,~0,QueryTriggerInteraction.Ignore);return hit?h.point.y:0;}).ToArray();File.WriteAllText(root+"/SourceAssets/F1_EnvironmentalStory/litter_ground.json",JsonConvert.SerializeObject(rows));return new{vertices=rows.Length};}}
